import json
L=json.load(open('loc_en.json',encoding='utf-8'))
want=['levelup_header','levelup_reroll','levelup_skip','levelup_banish','newItem_header','treasure_header','treasure_open','pause_resume','pause_quit','postGame_survived','postGame_goldEarned','gameOver_quit','gameOver_revive','genericPopup_new','powerupConfirm_maxed','levelup_footer','charConfirm_start','postGame_header','postGame_enemiesDefeated','postGame_levelReached','postGame_done','character_select_character_setup']
T={}
for k,v in L.items():
    s=v.replace(chr(92)+'n',chr(10)).strip(chr(10)).strip()
    if k.startswith('lang/weaponLevelUp_') or k.split('/',1)[1] in want: T[k.split('/',1)[1]]=s
out='// GENERATED by _evidence/gentext.py from the English localization table in resources.assets (official strings).\nconst __t='+json.dumps(T,indent=1,ensure_ascii=False)+';\nif(typeof window!=="undefined")window.VS_TEXT=__t;else module.exports=__t;\n'
open(r'D:\jogos\vampire-like\text.js','w',encoding='utf-8').write(out); print(len(T))
